#!/usr/bin/env python3
"""Rebuild the isolated agent from its archived parent-source copy.

Only --refresh-source reads the parent project; experiment runtime is standalone.
The active adapter retains the original SSE/ReAct loop and JSON action parser.
SDN-only tools and global configuration are replaced by explicit dependencies.
"""

import argparse
import ast
import difflib
import hashlib
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

ADAPTER = '''"""Wireless adaptation of the copied TKG-DTN NetworkRAGAgent.

Generated by tools/adapt_tkg_agent.py. Original source and provenance live in
vendor/tkg_dtn; the parent rag_system_agent.py is never imported or modified.
"""

from __future__ import annotations

import json
import logging
import re
from typing import Dict, Optional, Tuple

from .tools import TOOL_HELP

logger = logging.getLogger(__name__)


class NetworkRAGAgent:
    def __init__(self, llm, tools, max_iterations=8, memory_handler=None):
        self.llm = llm
        self.tools = tools
        self.max_iterations = max_iterations
        self.memory_handler = memory_handler
        self.chat_history = []
        self.graph_schema = json.dumps(tools.graph.schema(), ensure_ascii=False)

    def _decide_next_action(self, question, scratchpad):
        memory = self.memory_handler.retrieve(question) if self.memory_handler else ""
        prompt = f"""You are the TKG-DTN wireless network agent. Follow Thought -> Action -> Observation.
The task is sequential user admission into eMBB or URLLC, with resource allocation.
Read the current user and network state from the knowledge graph before deciding.
Use the supplied intent knowledge and the request to select the appropriate slice.
Plan suitable integer bandwidth for the request, respecting slice QoS and capacity.
Prefer plan_allocation without bandwidth initially to reuse the original resource proposal.
If a plan is invalid, inspect the actual violations. You may propose another integer bandwidth
within the same slice constraints; do not change a user's service category just to admit them.
Commit a valid plan, or reject with a specific reason if no suitable allocation is possible.
Never invent measurements, ground-truth labels, plan IDs, or successful tool outcomes.
The tools use the original simplified CQI-to-rate model. Latency is assigned, not measured.
Schema and relationship directions below describe a real Neo4j graph scoped to this run.

Tools:
{TOOL_HELP}

Graph Schema:
{self.graph_schema}

Memory: {memory or '(none)'}
Question: {question}
Observations from this request:
{scratchpad or '(none yet)'}

Return exactly one next action as:
思考: <brief decision rationale>
行动: {{"tool": "tool_name", "args": {{}}}}
"""
        return self.llm.complete([
            {"role": "system", "content": "You are a graph-grounded wireless resource agent. Use only observed facts and the listed tools."},
            {"role": "user", "content": prompt},
        ])

    def _run_tool(self, action):
        return self.tools.call(action.get("tool"), action.get("args", {}) or {})

    def _generate_final_answer(self, question, thought_trace):
        # Execution truth comes from the committed tool result. Do not ask an
        # extra LLM to invent an executable allocation in a natural-language answer.
        if self.tools.result is None:
            raise RuntimeError("ReAct ended without a committed allocation or explicit rejection")
        self.last_trace = thought_trace
        return json.dumps(self.tools.result, ensure_ascii=False)

'''


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--refresh-source", action="store_true")
    args = parser.parse_args()
    archive = ROOT / "vendor/tkg_dtn"
    archive.mkdir(parents=True, exist_ok=True)
    source = archive / "rag_system_agent.py"
    if args.refresh_source:
        original = ROOT.parent / "rag_system_agent.py"
        raw = original.read_bytes()
        text = re.sub(r'get\("password",\s*"[^"]*"\)', 'get("password", "[REMOVED_DEFAULT]")',
                      raw.decode("utf-8").replace("\r\n", "\n"))
        source.write_text(text, encoding="utf-8")
        (archive / "manifest.json").write_text(json.dumps({
            "source": "../rag_system_agent.py", "original_sha256": hashlib.sha256(raw).hexdigest(),
            "archived_sha256": hashlib.sha256(source.read_bytes()).hexdigest(),
            "sanitization": "Removed the old hard-coded Neo4j fallback password; line endings normalized.",
            "retained_methods": ["ask_stream", "_format_event", "_parse_llm_action"],
            "adaptations": ["Injected graph tools and shared logged LLM transport", "Wireless schema and task prompt",
                            "Full tool evidence in observations", "Stop after terminal action",
                            "Committed structured result replaces free-text execution answer"],
        }, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    text = source.read_text(encoding="utf-8")
    tree = ast.parse(text)
    cls = next(n for n in tree.body if isinstance(n, ast.ClassDef) and n.name == "NetworkRAGAgent")
    lines = text.splitlines(keepends=True)
    retained = []
    for name in ("ask_stream", "_format_event", "_parse_llm_action"):
        node = next(n for n in cls.body if isinstance(n, ast.FunctionDef) and n.name == name)
        fragment = "".join(lines[node.lineno - 1:node.end_lineno])
        if name == "ask_stream":
            fragment = fragment.replace('        yield self._format_event("status", "✅ 思考完成，正在生成最终答案...")',
                '            if self.tools.result is not None:\n                break\n\n        yield self._format_event("status", "正在返回已执行的网络决策...")')
        retained.append(fragment.rstrip() + "\n\n")
    output = ADAPTER + "".join(retained)
    target = ROOT / "wireless_exp/tkg/rag_system_agent.py"
    target.write_text(output, encoding="utf-8")
    (ROOT / "docs/TKG_AGENT_ADAPTATION.patch").write_text("".join(difflib.unified_diff(
        text.splitlines(keepends=True), output.splitlines(keepends=True),
        fromfile="vendor/tkg_dtn/rag_system_agent.py", tofile="wireless_exp/tkg/rag_system_agent.py",
    )), encoding="utf-8")
    print("Rebuilt", target.relative_to(ROOT))


if __name__ == "__main__":
    main()
